/**
 * Server-only password hashing helpers.
 *
 * Uses Node's built-in `crypto.scrypt` so we don't need an extra native
 * dependency just for password hashing (better-sqlite3 is already the one
 * native dependency this project needs).
 */
import crypto from 'node:crypto';

const KEY_LENGTH = 64;

export function generateSalt(): string {
  return crypto.randomBytes(16).toString('hex');
}

export function hashPassword(password: string, salt: string): string {
  return crypto.scryptSync(password, salt, KEY_LENGTH).toString('hex');
}

export function verifyPassword(password: string, salt: string, expectedHash: string): boolean {
  const actual = crypto.scryptSync(password, salt, KEY_LENGTH);
  const expected = Buffer.from(expectedHash, 'hex');
  if (actual.length !== expected.length) {
    return false;
  }
  return crypto.timingSafeEqual(actual, expected);
}

export function generateToken(): string {
  return crypto.randomBytes(32).toString('hex');
}

/**
 * Server-only SQLite access layer.
 *
 * This module is only ever imported from Qwik City server boundaries
 * (`plugin.ts` middleware, `routeLoader$`, and endpoint `onGet`/`onPost`/
 * `onDelete` handlers), so `better-sqlite3` never ends up in a client bundle.
 */
import fs from 'node:fs';
import path from 'node:path';
import Database from 'better-sqlite3';
import { generateSalt, hashPassword } from './crypto';

export type Role = 'admin' | 'editor' | 'viewer';

export interface UserRow {
  id: number;
  username: string;
  password_hash: string;
  salt: string;
  role: Role;
}

export interface PublicUser {
  id: number;
  username: string;
  role: Role;
}

export interface ContentRow {
  id: number;
  title: string;
  body: string;
}

let db: Database.Database | null = null;

function seed(database: Database.Database) {
  const userCount = (database.prepare('SELECT COUNT(*) as c FROM users').get() as { c: number }).c;

  if (userCount === 0) {
    const insertUser = database.prepare(
      'INSERT INTO users (username, password_hash, salt, role) VALUES (?, ?, ?, ?)',
    );

    const seedUsers: Array<{ username: string; password: string; role: Role }> = [
      { username: 'admin', password: 'Admin#123', role: 'admin' },
      { username: 'editor', password: 'Editor#123', role: 'editor' },
      { username: 'viewer', password: 'Viewer#123', role: 'viewer' },
    ];

    for (const user of seedUsers) {
      const salt = generateSalt();
      const passwordHash = hashPassword(user.password, salt);
      insertUser.run(user.username, passwordHash, salt, user.role);
    }
  }

  const contentCount = (database.prepare('SELECT COUNT(*) as c FROM content').get() as { c: number }).c;

  if (contentCount === 0) {
    const insertContent = database.prepare('INSERT INTO content (title, body) VALUES (?, ?)');
    insertContent.run('Getting Started', 'Welcome to the dashboard');
    insertContent.run('Company Roadmap', 'Plans for the next quarter');
  }
}

export function getDb(): Database.Database {
  if (db) {
    return db;
  }

  const dataDir = path.join(process.cwd(), 'data');
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  const dbPath = path.join(dataDir, 'app.db');
  const instance = new Database(dbPath);
  instance.pragma('journal_mode = WAL');
  instance.pragma('foreign_keys = ON');

  instance.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      salt TEXT NOT NULL,
      role TEXT NOT NULL CHECK (role IN ('admin', 'editor', 'viewer'))
    );

    CREATE TABLE IF NOT EXISTS content (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      body TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sessions (
      token TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      created_at INTEGER NOT NULL,
      FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
    );
  `);

  seed(instance);

  db = instance;
  return db;
}

export function findUserByUsername(username: string): UserRow | undefined {
  return getDb()
    .prepare('SELECT id, username, password_hash, salt, role FROM users WHERE username = ?')
    .get(username) as UserRow | undefined;
}

export function findUserById(id: number): UserRow | undefined {
  return getDb()
    .prepare('SELECT id, username, password_hash, salt, role FROM users WHERE id = ?')
    .get(id) as UserRow | undefined;
}

export function listUsers(): PublicUser[] {
  return getDb().prepare('SELECT id, username, role FROM users ORDER BY id').all() as PublicUser[];
}

export function createUser(username: string, password: string, role: Role): PublicUser {
  const salt = generateSalt();
  const passwordHash = hashPassword(password, salt);
  const result = getDb()
    .prepare('INSERT INTO users (username, password_hash, salt, role) VALUES (?, ?, ?, ?)')
    .run(username, passwordHash, salt, role);
  return { id: Number(result.lastInsertRowid), username, role };
}

export function listContent(): ContentRow[] {
  return getDb().prepare('SELECT id, title, body FROM content ORDER BY id').all() as ContentRow[];
}

export function createContent(title: string, body: string): ContentRow {
  const result = getDb().prepare('INSERT INTO content (title, body) VALUES (?, ?)').run(title, body);
  return { id: Number(result.lastInsertRowid), title, body };
}

export function deleteContent(id: number): boolean {
  const result = getDb().prepare('DELETE FROM content WHERE id = ?').run(id);
  return result.changes > 0;
}

/**
 * Server-only session management.
 *
 * Sessions are persisted in the same local SQLite database as everything
 * else, keyed by an opaque random token that is handed to the client only
 * via an HttpOnly cookie. The client never sees the user id/role directly;
 * every request re-derives it from the database.
 */
import { generateToken, verifyPassword } from './crypto';
import { findUserByUsername, getDb, type Role } from './db';

export interface SessionUser {
  id: number;
  username: string;
  role: Role;
}

export function login(username: string, password: string): SessionUser | null {
  const user = findUserByUsername(username);
  if (!user) {
    return null;
  }
  if (!verifyPassword(password, user.salt, user.password_hash)) {
    return null;
  }
  return { id: user.id, username: user.username, role: user.role };
}

export function createSession(userId: number): string {
  const token = generateToken();
  getDb()
    .prepare('INSERT INTO sessions (token, user_id, created_at) VALUES (?, ?, ?)')
    .run(token, userId, Date.now());
  return token;
}

export function getSessionUser(token: string | undefined | null): SessionUser | null {
  if (!token) {
    return null;
  }
  const row = getDb()
    .prepare(
      `SELECT users.id as id, users.username as username, users.role as role
       FROM sessions
       JOIN users ON users.id = sessions.user_id
       WHERE sessions.token = ?`,
    )
    .get(token) as SessionUser | undefined;
  return row ?? null;
}

export function deleteSession(token: string | undefined | null): void {
  if (!token) {
    return;
  }
  getDb().prepare('DELETE FROM sessions WHERE token = ?').run(token);
}

export function hasMinimumRole(role: Role, minimum: 'editor' | 'admin'): boolean {
  if (minimum === 'editor') {
    return role === 'editor' || role === 'admin';
  }
  return role === 'admin';
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { getSessionUser } from '~/lib/auth';

/**
 * Global request middleware. Runs for every request before any route
 * loader/action/endpoint handler.
 *
 * It resolves the current user (if any) from the `session` cookie by
 * looking the token up in the SQLite-backed sessions table, and stores the
 * result on `sharedMap` under the `user` key so downstream loaders and
 * endpoints can make authorization decisions without ever trusting
 * client-supplied data.
 */
export const onRequest: RequestHandler = async ({ cookie, sharedMap }) => {
  const token = cookie.get('session')?.value;
  const user = getSessionUser(token);
  sharedMap.set('user', user);
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { createSession, login } from '~/lib/auth';

async function readJsonBody(request: Request): Promise<Record<string, unknown>> {
  try {
    const data = await request.json();
    return data && typeof data === 'object' ? (data as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

export const onPost: RequestHandler = async (requestEvent) => {
  const body = await readJsonBody(requestEvent.request);
  const username = typeof body.username === 'string' ? body.username : '';
  const password = typeof body.password === 'string' ? body.password : '';

  const user = username && password ? login(username, password) : null;

  if (!user) {
    requestEvent.json(401, { error: 'Invalid username or password' });
    return;
  }

  const token = createSession(user.id);

  requestEvent.cookie.set('session', token, {
    httpOnly: true,
    path: '/',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24 * 7, // 7 days
  });

  requestEvent.json(200, { username: user.username, role: user.role });
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { deleteSession } from '~/lib/auth';

export const onPost: RequestHandler = async (requestEvent) => {
  const token = requestEvent.cookie.get('session')?.value;
  deleteSession(token);
  requestEvent.cookie.delete('session', { path: '/' });
  requestEvent.json(200, { success: true });
};

import type { RequestHandler } from '@builder.io/qwik-city';
import type { SessionUser } from '~/lib/auth';
import { createContent, listContent } from '~/lib/db';

async function readJsonBody(request: Request): Promise<Record<string, unknown>> {
  try {
    const data = await request.json();
    return data && typeof data === 'object' ? (data as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

export const onGet: RequestHandler = async (requestEvent) => {
  const user = requestEvent.sharedMap.get('user') as SessionUser | null;

  if (!user) {
    requestEvent.json(401, { error: 'Authentication required' });
    return;
  }

  requestEvent.json(200, listContent());
};

export const onPost: RequestHandler = async (requestEvent) => {
  const user = requestEvent.sharedMap.get('user') as SessionUser | null;

  if (!user) {
    requestEvent.json(401, { error: 'Authentication required' });
    return;
  }

  if (user.role !== 'editor' && user.role !== 'admin') {
    requestEvent.json(403, { error: 'Forbidden: editor or admin role required' });
    return;
  }

  const body = await readJsonBody(requestEvent.request);
  const title = typeof body.title === 'string' ? body.title : '';
  const contentBody = typeof body.body === 'string' ? body.body : '';

  // The client-supplied `id` (if any) is intentionally ignored; the
  // database always assigns the id.
  const created = createContent(title, contentBody);

  requestEvent.json(201, created);
};

import type { RequestHandler } from '@builder.io/qwik-city';
import type { SessionUser } from '~/lib/auth';
import { deleteContent } from '~/lib/db';

export const onDelete: RequestHandler = async (requestEvent) => {
  const user = requestEvent.sharedMap.get('user') as SessionUser | null;

  if (!user) {
    requestEvent.json(401, { error: 'Authentication required' });
    return;
  }

  if (user.role !== 'editor' && user.role !== 'admin') {
    requestEvent.json(403, { error: 'Forbidden: editor or admin role required' });
    return;
  }

  const id = Number(requestEvent.params.id);

  if (!Number.isInteger(id)) {
    requestEvent.json(404, { error: 'Not found' });
    return;
  }

  const deleted = deleteContent(id);

  if (!deleted) {
    requestEvent.json(404, { error: 'Not found' });
    return;
  }

  requestEvent.json(200, { success: true });
};

import type { RequestHandler } from '@builder.io/qwik-city';
import type { SessionUser } from '~/lib/auth';
import { createUser, listUsers, type Role } from '~/lib/db';

const VALID_ROLES: Role[] = ['admin', 'editor', 'viewer'];

async function readJsonBody(request: Request): Promise<Record<string, unknown>> {
  try {
    const data = await request.json();
    return data && typeof data === 'object' ? (data as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

export const onGet: RequestHandler = async (requestEvent) => {
  const user = requestEvent.sharedMap.get('user') as SessionUser | null;

  if (!user) {
    requestEvent.json(401, { error: 'Authentication required' });
    return;
  }

  if (user.role !== 'admin') {
    requestEvent.json(403, { error: 'Forbidden: admin role required' });
    return;
  }

  // listUsers() never selects the password hash/salt columns.
  requestEvent.json(200, listUsers());
};

export const onPost: RequestHandler = async (requestEvent) => {
  const user = requestEvent.sharedMap.get('user') as SessionUser | null;

  if (!user) {
    requestEvent.json(401, { error: 'Authentication required' });
    return;
  }

  if (user.role !== 'admin') {
    requestEvent.json(403, { error: 'Forbidden: admin role required' });
    return;
  }

  const body = await readJsonBody(requestEvent.request);
  const username = typeof body.username === 'string' ? body.username.trim() : '';
  const password = typeof body.password === 'string' ? body.password : '';
  const role = typeof body.role === 'string' ? (body.role as Role) : ('' as Role);

  if (!username || !password || !VALID_ROLES.includes(role)) {
    requestEvent.json(400, { error: 'username, password and a valid role (admin/editor/viewer) are required' });
    return;
  }

  try {
    const created = createUser(username, password, role);
    requestEvent.json(201, created);
  } catch {
    requestEvent.json(400, { error: 'Username already exists' });
  }
};

import { $, component$, useSignal } from '@builder.io/qwik';
import { type DocumentHead, useNavigate } from '@builder.io/qwik-city';

export default component$(() => {
  const username = useSignal('');
  const password = useSignal('');
  const error = useSignal('');
  const submitting = useSignal(false);
  const nav = useNavigate();

  const submit = $(async () => {
    error.value = '';
    submitting.value = true;
    try {
      const res = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: username.value, password: password.value }),
      });

      if (res.ok) {
        await nav('/');
        return;
      }

      const data = await res.json().catch(() => ({}));
      error.value = typeof data.error === 'string' ? data.error : 'Login failed';
    } finally {
      submitting.value = false;
    }
  });

  return (
    <div class="login-page">
      <h1>Login</h1>
      <form preventdefault:submit onSubmit$={submit}>
        <div>
          <label for="username">Username</label>
          <input
            id="username"
            name="username"
            type="text"
            autocomplete="username"
            value={username.value}
            onInput$={(_, el) => (username.value = el.value)}
          />
        </div>
        <div>
